def equal_thirds(xs):
    total = sum(xs)
    if total % 3 != 0:
        return 0
    third = total // 3
    ways, firsts, prefix = 0, 0, 0
    for j in range(len(xs) - 1):
        prefix += xs[j]
        if prefix == 2 * third:
            ways += firsts
        if prefix == third:
            firsts += 1
    return ways

def mistakes_summary(log):
    counts = {}
    for problem, category in log:
        counts[category] = counts.get(category, 0) + 1
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
